from operator import add, mul

def priority_operator(precedence: int, operands: list, operators: list, operator_dict):
    if len(operators) > 1:
        i = max(j for j in range(len(operators) - 1, -1, -1) if operator_dict[operators[j]] > precedence)
    else:
        return 0

    if i < len(operators):
        op = operators.pop(i)
        if op == '*':
            opn = operands.pop(i)
            operands[i - 1] = operator_dict[op](operands[i - 1], opn)
        else:  # '+' case
            opn = operands.pop(i)
            operands[i - 1] = operator_dict[op](operands[i - 1], opn)
    return i if i < len(operators) else 0

def operate(operators: list, operands: list, operator_dict):
    while operators:
        for precedence in range(max(operator_dict.values()), -1, -1):
            priority_operator(precedence, operands[:], operators[:], operator_dict)
    return operands[0]

def f(inputs: List[Tuple[int, str]]):
