    result = []
    for n, s in inputs:
        s = s.replace(" ", "")
        operator_precedence = {op: prio for prio, op in enumerate("+*")}
        operators = []
        operands = []
        brackets = []

        for char in s:
            if char.isnumeric():
                operands.append(int(char))
            elif char in operator_precedence:
